"use client";
import Image from "next/image";
import Link from "next/link";
import { useState, useEffect } from "react";
import { usePathname } from "next/navigation";

export default function Navbar() {
  const [showFloating, setShowFloating] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const pathname = usePathname();

  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 80) {
        setShowFloating(true);
      } else {
        setShowFloating(false);
      }
    };
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  // Hide Home menu on home page
  const isHome = pathname === "/";
  const navLinks = [
    { href: "/", label: "Home" },
    { href: "/careers", label: "Careers" },
    { href: "/blog", label: "Blog" },
    { href: "/services", label: "Services" },
  ].filter(link => !(isHome && link.href === "/"));

  // Highlight style matches Contact Us button
  const highlightClass =
    "bg-gradient-to-r from-thitech-blue-dark to-thitech-blue text-white px-5 py-[10px] rounded-[30px] font-bold";

  return (
    <>
      {/* Static Bar always visible at top */}
      <div className="h-[10%]">
        <header className="px-5 bg-white" style={{ opacity: 1, transform: 'none' }}>
          <div className="header-container sizer flex items-center justify-between py-5 max-w-5xl mx-auto">
            <div className="header-left max-w-[200px]">
              <Link href="/" className="w-full h-full block">
                <Image src="https://thitech.in/thitech-logo-pack/thitech-logo-transparent-cropped-small.png" alt="Thitech Logo" width={120} height={40} className="object-contain w-full h-full" />
              </Link>
            </div>
            <div className="header-right text-gray-900 hidden md:block">
              <ul className="flex font-medium items-center gap-3">
                {navLinks.map((link) => (
                  <li key={link.href} className={
                    pathname === link.href
                      ? highlightClass
                      : "hover:bg-thitech-blue-light px-5 py-[10px] rounded-[30px] transition"
                  }>
                    <Link href={link.href}>{link.label}</Link>
                  </li>
                ))}
                <li className={highlightClass + " ml-2"}>
                  <Link className="flex items-center gap-2" href="#contact">
                    Contact Us
                    <span className="rounded-full bg-white text-thitech-blue-dark p-1">
                      <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="lucide lucide-arrow-right animate-bounce-x"><path d="M5 12h14"></path><path d="m12 5 7 7-7 7"></path></svg>
                    </span>
                  </Link>
                </li>
              </ul>
            </div>
            <div className="md:hidden text-gray-900">
              <button
                onClick={() => setMenuOpen(!menuOpen)}
                aria-label="Open menu"
              >
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  width="32"
                  height="32"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  className="lucide lucide-menu cursor-pointer"
                >
                  <line x1="4" x2="20" y1="12" y2="12"></line>
                  <line x1="4" x2="20" y1="6" y2="6"></line>
                  <line x1="4" x2="20" y1="18" y2="18"></line>
                </svg>
              </button>
              {menuOpen && (
                <div className="absolute right-0 mt-2 bg-white rounded-xl shadow-lg py-2 px-4 flex flex-col gap-2 z-30">
                  {navLinks.map((link) => (
                    <Link
                      key={link.href}
                      href={link.href}
                      className={
                        pathname === link.href
                          ? highlightClass + " text-center"
                          : "py-2 px-5 rounded-[30px] text-center hover:bg-thitech-blue-light"
                      }
                      onClick={() => setMenuOpen(false)}
                    >
                      {link.label}
                    </Link>
                  ))}
                  <Link
                    href="#contact"
                    className={highlightClass + " text-center mt-1"}
                    onClick={() => setMenuOpen(false)}
                  >
                    Contact Us
                  </Link>
                </div>
              )}
            </div>
          </div>
        </header>
      </div>
      {/* Floating Bar (shows after static bar is scrolled out) */}
      {showFloating && (
        <nav className="w-full fixed top-0 z-30 flex justify-center animate-fade-in">
          <div className="header-container backdrop-blur-xl shadow-lg border border-white/10 rounded-full flex items-center justify-between py-2 bg-white/10 px-5 max-w-5xl w-full mx-4 mt-2">
            <div className="header-left max-w-[200px]">
              <Link href="/" className="w-full h-full block">
                <Image src="https://thitech.in/thitech-logo-pack/thitech-logo-transparent-cropped-small.png" alt="Thitech Logo" width={120} height={40} className="object-contain w-full h-full" />
              </Link>
            </div>
            <div className="header-right text-gray-900 hidden md:block">
              <ul className="flex font-medium items-center gap-3">
                {navLinks.map((link) => (
                  <li key={link.href} className={
                    pathname === link.href
                      ? highlightClass
                      : "hover:bg-thitech-blue-light px-5 py-[10px] rounded-[30px] transition"
                  }>
                    <Link href={link.href}>{link.label}</Link>
                  </li>
                ))}
                <li className={highlightClass + " ml-2"}>
                  <Link className="flex items-center gap-2" href="#contact">
                    Contact Us
                    <span className="rounded-full bg-white text-thitech-blue-dark p-1">
                      <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="lucide lucide-arrow-right animate-bounce-x"><path d="M5 12h14"></path><path d="m12 5 7 7-7 7"></path></svg>
                    </span>
                  </Link>
                </li>
              </ul>
            </div>
            <div className="md:hidden text-gray-900">
              <button
                onClick={() => setMenuOpen(!menuOpen)}
                aria-label="Open menu"
              >
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  width="32"
                  height="32"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  className="lucide lucide-menu cursor-pointer"
                >
                  <line x1="4" x2="20" y1="12" y2="12"></line>
                  <line x1="4" x2="20" y1="6" y2="6"></line>
                  <line x1="4" x2="20" y1="18" y2="18"></line>
                </svg>
              </button>
              {menuOpen && (
                <div className="absolute right-0 mt-2 bg-white rounded-xl shadow-lg py-2 px-4 flex flex-col gap-2 z-30">
                  {navLinks.map((link) => (
                    <Link
                      key={link.href}
                      href={link.href}
                      className={
                        pathname === link.href
                          ? highlightClass + " text-center"
                          : "py-2 px-5 rounded-[30px] text-center hover:text-thitech-blue-light"
                      }
                      onClick={() => setMenuOpen(false)}
                    >
                      {link.label}
                    </Link>
                  ))}
                  <Link
                    href="#contact"
                    className={highlightClass + " text-center mt-1"}
                    onClick={() => setMenuOpen(false)}
                  >
                    Contact Us
                  </Link>
                </div>
              )}
            </div>
          </div>
        </nav>
      )}
    </>
  );
}
